<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\WebAuthn\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigReadGateway;
use Civi\Lughauth\Features\Oidc\WebAuthn\Application\Usecase\BeginRegistration\BeginRegistrationUsecase;
use Civi\Lughauth\Features\Oidc\WebAuthn\Application\Usecase\FinishRegistration\FinishRegistrationUsecase;
use Civi\Lughauth\Features\Oidc\WebAuthn\Application\Usecase\BeginAuthentication\BeginAuthenticationUsecase;
use Civi\Lughauth\Features\Oidc\WebAuthn\Application\Usecase\FinishAuthentication\FinishAuthenticationUsecase;
use OpenApi\Attributes as OA;

final class WebAuthnController
{
    public function __construct(
        private readonly Context $context,
        private readonly TenantReadGateway $tenants,
        private readonly TenantConfigReadGateway $tenantConfigs,
        private readonly BeginRegistrationUsecase $beginRegistration,
        private readonly FinishRegistrationUsecase $finishRegistration,
        private readonly BeginAuthenticationUsecase $beginAuthentication,
        private readonly FinishAuthenticationUsecase $finishAuthentication,
    ) {
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/webauthn/register/begin',
        summary: 'Begin WebAuthn credential registration',
        tags: ['WebAuthn'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(response: 200, description: 'PublicKeyCredentialCreationOptions'),
            new OA\Response(response: 401, description: 'Unauthenticated'),
        ]
    )]
    public function registerBegin(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'] ?? '';
        $identity = $this->context->getIdentity();
        if ($identity->anonymous) {
            throw new UnauthorizedException('Authentication required for WebAuthn registration');
        }

        $userUid = $identity->id ?? '';
        [$rpId, $rpName] = $this->resolveRp($tenant);

        $options = $this->beginRegistration->begin($userUid, $tenant, $rpId, $rpName);

        $response->getBody()->write(json_encode($options, JSON_UNESCAPED_SLASHES) ?: '{}');
        return $response->withHeader('Content-Type', 'application/json');
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/webauthn/register/finish',
        summary: 'Finish WebAuthn credential registration',
        tags: ['WebAuthn'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(response: 200, description: 'Registration successful'),
            new OA\Response(response: 400, description: 'Verification failed'),
            new OA\Response(response: 401, description: 'Unauthenticated'),
        ]
    )]
    public function registerFinish(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'] ?? '';
        $identity = $this->context->getIdentity();
        if ($identity->anonymous) {
            throw new UnauthorizedException('Authentication required for WebAuthn registration');
        }

        $body = $this->parseJsonBody($request);
        $challengeId = (string) ($body['challengeId'] ?? '');
        $clientCredential = is_array($body['credential'] ?? null)
            ? $body['credential']
            : (array) json_decode((string) ($body['credential'] ?? '{}'), true);
        $deviceName = (string) ($body['deviceName'] ?? '');

        [$rpId] = $this->resolveRp($tenant);
        $origin = $this->resolveOrigin($request);

        $this->finishRegistration->finish(
            $challengeId,
            $tenant,
            $clientCredential,
            $origin,
            $rpId,
            $deviceName !== '' ? $deviceName : null,
        );

        $response->getBody()->write(json_encode(['status' => 'ok']) ?: '{}');
        return $response->withHeader('Content-Type', 'application/json');
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/webauthn/authenticate/begin',
        summary: 'Begin WebAuthn authentication',
        tags: ['WebAuthn'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(response: 200, description: 'PublicKeyCredentialRequestOptions'),
        ]
    )]
    public function authenticateBegin(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'] ?? '';
        [$rpId] = $this->resolveRp($tenant);

        $options = $this->beginAuthentication->begin($tenant, $rpId);

        $response->getBody()->write(json_encode($options, JSON_UNESCAPED_SLASHES) ?: '{}');
        return $response->withHeader('Content-Type', 'application/json');
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/webauthn/authenticate/finish',
        summary: 'Finish WebAuthn authentication',
        tags: ['WebAuthn'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(response: 200, description: 'Authentication successful, returns challengeId for OIDC flow'),
            new OA\Response(response: 401, description: 'Assertion verification failed'),
        ]
    )]
    public function authenticateFinish(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'] ?? '';
        $body = $this->parseJsonBody($request);
        $challengeId = (string) ($body['challengeId'] ?? '');
        $clientCredential = is_array($body['credential'] ?? null)
            ? $body['credential']
            : (array) json_decode((string) ($body['credential'] ?? '{}'), true);

        [$rpId] = $this->resolveRp($tenant);
        $origin = $this->resolveOrigin($request);

        $result = $this->finishAuthentication->finish(
            $challengeId,
            $tenant,
            $clientCredential,
            $origin,
            $rpId,
        );

        $response->getBody()->write(json_encode([
            'status' => 'ok',
            'challengeId' => $challengeId,
        ], JSON_UNESCAPED_SLASHES) ?: '{}');
        return $response->withHeader('Content-Type', 'application/json');
    }

    private function resolveRp(string $tenant): array
    {
        $tenantObj = $this->tenants->findOneByName($tenant);
        $config = $tenantObj ? $this->tenantConfigs->findOneByTenant($tenantObj) : null;
        $rpId = ($config?->getWebauthnRpId()) ?? parse_url($this->resolveOriginFromEnv(), PHP_URL_HOST) ?? $tenant;
        $rpName = ($config?->getWebauthnRpName()) ?? $tenant;
        return [$rpId, $rpName];
    }

    private function resolveOrigin(ServerRequestInterface $request): string
    {
        $origin = $request->getHeaderLine('Origin');
        if ($origin !== '') {
            return $origin;
        }
        return $this->resolveOriginFromEnv();
    }

    private function resolveOriginFromEnv(): string
    {
        return (string) ($_ENV['APP_ORIGIN'] ?? $_SERVER['APP_ORIGIN'] ?? 'https://localhost');
    }

    private function parseJsonBody(ServerRequestInterface $request): array
    {
        $parsed = $request->getParsedBody();
        if (is_array($parsed) && !empty($parsed)) {
            return $parsed;
        }
        $raw = (string) $request->getBody();
        if ($raw !== '') {
            $decoded = json_decode($raw, true);
            if (is_array($decoded)) {
                return $decoded;
            }
        }
        return [];
    }
}
